// Cada alerta entrante tiene la estructura:
// {
//   timestamp, cultivo, parcela, ubicacion, variable,
//   valor, unidad, nivel, mensaje, accion
// }
const a = msg.payload;
if (typeof a !== 'object' || !a.nivel) return null;

// Mantener contador acumulado en flow context
const contadores = flow.get('contadores_alertas') || { info: 0, warning: 0, critical: 0 };
contadores[a.nivel] = (contadores[a.nivel] || 0) + 1;
flow.set('contadores_alertas', contadores);

// Mantener historial de las últimas 20 alertas
const historial = flow.get('historial_alertas') || [];
historial.unshift({
    hora:      new Date(a.timestamp).toLocaleTimeString('es-CO'),
    nivel:     a.nivel.toUpperCase(),
    parcela:   a.parcela,
    cultivo:   a.cultivo,
    variable:  a.variable,
    valor:     `${a.valor} ${a.unidad || ''}`,
    mensaje:   a.mensaje
});
if (historial.length > 20) historial.pop();
flow.set('historial_alertas', historial);

// Output 1: actualización del contador (gauge/widget)
const msg_contador = { payload: contadores, topic: 'contadores' };
// Output 2: tabla de historial
const msg_tabla = { payload: historial, topic: 'historial' };
// Output 3: alerta enriquecida (para logging adicional)
const msg_full = { payload: a, topic: 'alerta_completa' };

return [msg_contador, msg_tabla, msg_full];

// Filtro: solo dejar pasar alertas críticas
if (msg.payload && msg.payload.nivel === 'critical') {
    return msg;
}
return null;
